annotations.source:
-- V3 parses a bare `@name` annotation and then ignores it.
-- It carries no semantics, and it must NOT take arguments:
-- `@rival(meiya)` does not parse as an annotation in V3.
@protagonist
task hero() -> word {
    give back "Shirogane Takeru"
}

@deprecated
task legacy() -> word {
    give back "old path"
}

@season_finale
task main() -> void {
    say hero()
    say legacy()
}

book_break_continue.source:
-- break leaves the loop; continue skips to its next pass.
task main() {
    pilot mut n = 0
    repeat 10 times {
        n += 1
        if n % 2 == 0 { continue }     -- skip the even numbers
        if n > 7 { break }             -- and stop after 7
        say n
    }
    say "stopped at {n}"

    -- In nested loops, both act on the innermost loop only.
    pilot mut row = 1
    repeat 3 times {
        pilot mut column = 1
        repeat 3 times {
            if column > row { break }
            say "{row},{column}"
            column += 1
        }
        row += 1
    }
}

book_by_value.source:
-- A task receives its own copy of each number, word and bool it is given.
task refuel(level: int) -> int {
    level = level + 40          -- changes the copy
    give back level
}

task main() {
    pilot fuel = 50
    pilot after = refuel(fuel)

    say fuel                    -- still 50
    say after
}

book_collatz.source:
-- collatz.fk: how many steps does a number take to reach 1?
-- Halve it when it is even; otherwise triple it and add one.
task collatz_steps(start: int) -> int {
    pilot mut n = start
    pilot mut steps = 0

    training arc until n == 1 max 1000 sessions {
        if n % 2 == 0 {
            n = n / 2
        } else {
            n = 3 * n + 1
        }
        steps += 1
    }

    if n != 1 { give back -1 }         -- ran out of sessions
    give back steps
}

task main() {
    pilot mut start = 1
    pilot mut longest = 0
    pilot mut longest_start = 1

    repeat 30 times {
        pilot steps = collatz_steps(start)
        if steps > longest {
            longest = steps
            longest_start = start
        }
        start += 1
    }

    pilot six = collatz_steps(6)
    pilot twenty_seven = collatz_steps(27)
    say "6 takes {six} steps"
    say "27 takes {twenty_seven} steps"
    say "below 31, the longest chain starts at {longest_start} ({longest} steps)"
}

