book_constants.source:
-- Pilots declared outside every task are visible to all of them.
fixed pilot MAX_SORTIES: int = 3
fixed pilot SQUADRON: word = "Valkyries"

task briefing() {
    say "{SQUADRON}: at most {MAX_SORTIES} sorties today"
}

task main() {
    briefing()
    say MAX_SORTIES * 2
}

book_contextual_words.source:
-- These words are used by the language and are not reserved.
-- The program builds. It is here as a warning, not as a model.
task twice(int: int) -> int {
    pilot give = int * 2
    give back give
}

task main() {
    pilot mut training = 0
    pilot arc = 3
    training arc until training >= arc max 10 sessions {
        training += 1
    }
    pilot ask = twice(training)
    say "training {training}, ask {ask}"
}

book_exit_code.source:
-- When `main` gives back an int, that number is the program's exit code.
task main() -> int {
    say "preflight failed: fuel line"
    give back 3
}

book_fizzbuzz.source:
-- fizzbuzz.fk: count from 1 to 15. Multiples of 3 say Fizz, multiples of 5
-- say Buzz, and multiples of both say FizzBuzz.
task label(n: int) -> word {
    if n % 15 == 0 { give back "FizzBuzz" }
    if n % 3 == 0 { give back "Fizz" }
    if n % 5 == 0 { give back "Buzz" }
    give back n.to_word()
}

task main() {
    pilot mut n = 1
    repeat 15 times {
        say label(n)
        n += 1
    }
}

book_for_each.source:
-- for each: visit every element of a list, in order.
task main() {
    pilot squadron = ["Takeru", "Meiya", "Sumika"]

    for each name in squadron {
        say "{name}, report in"
    }

    -- The loop gives you the element, not its position. Count it yourself.
    pilot mut position = 1
    for each name in squadron {
        say "{position}. {name}"
        position += 1
    }

    -- break and continue work here too.
    pilot readings = [12, 0, 7, 0, 30, 99]
    pilot mut total = 0
    for each reading in readings {
        if reading == 0 { continue }
        if reading > 50 { break }
        total += reading
    }
    say total
}

book_give_back.source:
-- `give back` leaves the task at once, from wherever it is.
task rank_for(sorties: int) -> word {
    if sorties >= 50 { give back "veteran" }
    if sorties >= 10 { give back "regular" }
    give back "rookie"
}

-- In a task with no return type, a bare `give back` simply leaves early.
task announce(message: word) {
    if message == "" { give back }
    say message.to_upper()
}

task main() {
    say rank_for(64)
    say rank_for(12)
    say rank_for(3)

    announce("")
    announce("all units, stand by")
}

book_guess.source:
-- guess.fk: the finished guessing game.
--
-- Run it with no arguments to play against the clock's choice of secret.
-- Pass a number (`./guess 42`) to fix the secret, which is how this
-- program is tested.

task secret_number() -> int {
    if process::args_count() > 1 {
        pilot chosen = process::arg(1).parse_int()
        if parse_status() == 0 { give back chosen }
        parse_clear_status()            -- not a number: fall back to the clock
    }
    pilot micros = time::monotonic_ns() / 1000
    give back micros % 100 + 1
}

task main() {
    say "Guess the number! It is between 1 and 100."

    pilot secret = secret_number()
    pilot mut attempts = 0
    pilot mut solved = false

    repeat until solved {
        pilot text = ask("Your guess: ")

        -- An empty line means the input ended (or the player just pressed
        -- Enter). Stop instead of asking forever.
        if text.trim() == "" {
            say "No guess given. The number was {secret}."
            break
        }

        pilot guess = text.trim().parse_int()
        if parse_status() != 0 {
            parse_clear_status()
            say "'{text}' is not a whole number. Try again."
            continue
        }

        attempts += 1

        if guess < secret {
            say "Too low."
        } else if guess > secret {
            say "Too high."
        } else {
            solved = true
        }
    }

    if solved {
        if attempts == 1 {
            say "You got it in one guess!"
        } else {
            say "You got it in {attempts} guesses!"
        }
    }
}

book_guess_compare.source:
-- Step 4: compare one guess with the secret.
task main() {
    pilot secret = 42

    pilot text = ask("Your guess: ")
    pilot guess = text.trim().parse_int()

    if guess < secret {
        say "Too low."
    } else if guess > secret {
        say "Too high."
    } else {
        say "You got it!"
    }
}

book_guess_input.source:
-- Step 1: ask a question and keep the answer.
task main() {
    say "Guess the number!"

    pilot guess = ask("Your guess: ")
    say "You guessed: {guess}"
}

book_guess_parse.source:
-- Step 2: turn the typed text into a number, and notice when it is not one.
task main() {
    pilot text = ask("Your guess: ")

    pilot guess = text.trim().parse_int()
    if parse_status() != 0 {
        parse_clear_status()
        say "'{text}' is not a whole number."
    } else {
        pilot doubled = guess * 2
        say "Twice your guess is {doubled}."
    }
}

book_guess_secret.source:
-- Step 3: a secret number between 1 and 100.
-- V3 has no random-number library, so the clock supplies the unpredictability.
task secret_number() -> int {
    pilot micros = time::monotonic_ns() / 1000
    give back micros % 100 + 1
}

task main() {
    pilot secret = secret_number()
    if secret >= 1 and secret <= 100 {
        say "The secret is somewhere from 1 to 100."
    } else {
        say "Something is wrong with the secret: {secret}"
    }
}

